<?php declare(strict_types=1);$db=new PDO('sqlite:'.__DIR__.'/data/cartorio.sqlite');$db->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);$db->exec('CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT,username TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT "admin")');if((int)$db->query('SELECT COUNT(*) FROM users')->fetchColumn()>0){header('Location: admin.php');exit;}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){$u=trim((string)($_POST['username']??''));$p=(string)($_POST['password']??'');if($u===''||strlen($p)<8)$error='Informe usuário e senha com pelo menos 8 caracteres.';else{$s=$db->prepare('INSERT INTO users(username,password_hash,role) VALUES(?,?,?)');$s->execute([$u,password_hash($p,PASSWORD_DEFAULT),'admin']);header('Location: admin.php');exit;}}?><!doctype html><meta charset="utf-8"><title>Configurar Cartório</title><style>body{font:16px Arial;max-width:420px;margin:12vh auto;padding:24px}input,button{display:block;width:100%;padding:12px;margin:10px 0;box-sizing:border-box}</style><h1>Primeiro acesso</h1><p>Crie o usuário administrador deste beta.</p><?php if($error):?><p><?=htmlspecialchars($error)?></p><?php endif;?><form method="post"><input name="username" placeholder="Usuário" required><input name="password" type="password" placeholder="Senha (mín. 8 caracteres)" required><button>Criar acesso</button></form>
